begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('e1000000-0000-0000-0000-000000000001','automation-owner@test.invalid'),('e1000000-0000-0000-0000-000000000002','automation-other@test.invalid');
insert into public.tenants(id,name,slug)values('e2000000-0000-0000-0000-000000000001','Automation A','automation-a'),('e2000000-0000-0000-0000-000000000002','Automation B','automation-b');
insert into public.properties(id,tenant_id,name,property_type)values('e3000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Hotel A','hotel'),('e3000000-0000-0000-0000-000000000002','e2000000-0000-0000-0000-000000000002','Hotel B','hotel');
insert into public.tenant_memberships(tenant_id,user_id,role)values('e2000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','owner'),('e2000000-0000-0000-0000-000000000002','e1000000-0000-0000-0000-000000000002','owner');
insert into public.guests(id,tenant_id,full_name,phone)values('e4000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Asha','+919111111111');
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency,created_at)values('e5000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','e4000000-0000-0000-0000-000000000001','confirmed',current_date,current_date+2,5000,'INR',now()-interval '1 day');
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,display_phone,credentials_ref)values('e6000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','12345678001','12345678002','+919999999999','automation-test');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.save_whatsapp_guest_menu('e3000000-0000-0000-0000-000000000001',0,true,'{"intro":"Welcome. How can we help?","items":[{"action":"stay","label":"My stay","enabled":true},{"action":"location","label":"Directions","enabled":true},{"action":"photos","label":"Hotel photos","enabled":true},{"action":"reception","label":"Reception","enabled":true}],"maps_url":"https://maps.google.com/hotel","review_url":"https://example.com/review","website_url":"https://example.com","photos":[{"url":"https://example.com/hotel.jpg","caption":"Hotel exterior"},{"url":"https://example.com/room.png","caption":"Deluxe room"}]}');
select throws_ok($$select public.save_whatsapp_guest_menu('e3000000-0000-0000-0000-000000000002',0,false,'{}')$$,'42501',null,'cannot configure another hotel');
select throws_ok($$select public.save_whatsapp_guest_menu('e3000000-0000-0000-0000-000000000001',0,false,'{}')$$,'40001',null,'configuration uses optimistic concurrency');
select is(public.whatsapp_guest_menu_context('e3000000-0000-0000-0000-000000000001')->>'enabled','true','owner can inspect live menu status');
reset role;
select is((select data->>'review_url'from public.whatsapp_guest_settings where property_id='e3000000-0000-0000-0000-000000000001'),'https://example.com/review','review automation and menu share hotel link settings');
select ok(not private.whatsapp_public_link('https://127.0.0.1/photo.jpg'),'private photo URL rejected');
select ok(not private.whatsapp_public_link('https://user:secret@example.com/photo.jpg'),'credential URL rejected');
set local role service_role;
select set_config('test.guest_conv',public.ingest_whatsapp_inbound('12345678001','msg:concierge-hi','919111111111','Asha','concierge-hi','text','Hi','{}')::text,true);
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),1,'Hi queues one live guest menu');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),0,'dispatcher is idempotent');
select is(public.ingest_whatsapp_inbound('12345678001','msg:concierge-hi','919111111111','Asha','concierge-hi','text','Hi','{}'),null::uuid,'provider replay is ignored');
select is((select outbound_payload#>>'{interactive,type}'from public.messages where guest_menu_action='menu'and conversation_id=current_setting('test.guest_conv')::uuid),'list','menu uses real interactive list payload');
select is((select jsonb_array_length(outbound_payload#>'{interactive,action,sections,0,rows}')from public.messages where guest_menu_action='menu'and conversation_id=current_setting('test.guest_conv')::uuid),4,'only configured options are shown');
select is((select count(*)::int from public.claim_outbound_messages_v4(10,false,true)),0,'old worker is fenced from rich replies');
select is((select count(*)::int from public.claim_outbound_messages_v5(10,false,true)),1,'new worker claims rich menu');
select is((select count(*)::int from public.claim_outbound_messages_v5(10,false,true)),0,'claimed menu cannot be claimed twice');
reset role;
update public.messages set status='sent'where conversation_id=current_setting('test.guest_conv')::uuid and direction='out';
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','msg:concierge-private','919111111111','Asha','concierge-private','interactive','[interactive]','{"interactive":{"type":"list_reply","list_reply":{"id":"guest:stay","title":"My stay"}}}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),1,'unknown guest receives verification guidance');
select ok((select body like '%verify your stay%'from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='concierge-private')and direction='out'),'private information is not guessed from phone number');
select is((select count(*)::int from public.guest_access_tokens where reservation_id='e5000000-0000-0000-0000-000000000001'),0,'unverified requester gets no private token');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.authorize_whatsapp_stay_updates('e3000000-0000-0000-0000-000000000001','e5000000-0000-0000-0000-000000000001',0,'granted','Guest identity and WhatsApp number verified at reception.',true);
reset role;set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','msg:concierge-verified','919111111111','Asha','concierge-verified','interactive','[interactive]','{"interactive":{"type":"list_reply","list_reply":{"id":"guest:stay","title":"My stay"}}}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),1,'verified guest gets personal stay button');
select ok((select outbound_payload#>>'{interactive,action,parameters,url}'~'^https://guest.test/s/[a-f0-9]{64}$'from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='concierge-verified')and direction='out'),'private URL uses trusted host and a fresh reservation token');
select is((select count(*)::int from public.guest_access_tokens where reservation_id='e5000000-0000-0000-0000-000000000001'),1,'one reservation token issued');
reset role;
update public.whatsapp_guest_authorizations set status='revoked',version=version+1 where conversation_id=current_setting('test.guest_conv')::uuid;
select is(private.inbox_delivery_error((select id from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='concierge-verified')and direction='out')),'Private guest access changed. Verify the stay again.','permission revocation suppresses queued private link');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','msg:concierge-photos','919111111111','Asha','concierge-photos','interactive','[interactive]','{"interactive":{"type":"list_reply","list_reply":{"id":"guest:photos","title":"Hotel photos"}}}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),1,'photo request accepted');
select is((select count(*)::int from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='concierge-photos')and direction='out'),2,'guest receives configured gallery only');
select is((select outbound_payload#>>'{image,link}'from public.messages where guest_menu_action='photos:0'and conversation_id=current_setting('test.guest_conv')::uuid),'https://example.com/hotel.jpg','first photo payload uses configured public image');
select public.ingest_whatsapp_inbound('12345678001','msg:concierge-handoff','919111111111','Asha','concierge-handoff','text','RECEPTION','{}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),1,'reception selection queues an acknowledgment');
select is((select human_handoff from public.conversations where id=current_setting('test.guest_conv')::uuid),true,'reception selection pauses automation');
reset role;
select is(private.inbox_delivery_error((select id from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='concierge-handoff')and direction='out')),null::text,'handoff acknowledgment remains deliverable');
select is(private.inbox_delivery_error((select id from public.messages where guest_menu_action='photos:0'and conversation_id=current_setting('test.guest_conv')::uuid)),'Automatic replies paused or handed to reception.','handoff suppresses queued photo automation');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','msg:concierge-human','919111111111','Asha','concierge-human','text','MENU','{}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),0,'human conversation never gets auto-menu');
select public.ingest_whatsapp_inbound('12345678001','msg:concierge-stop','919111111111','Asha','concierge-stop','text','STOP','{}');
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),0,'STOP never produces an automated menu');
reset role;
select ok(private.is_opted_out('e3000000-0000-0000-0000-000000000001','919111111111'),'STOP still records the existing contact opt-out');
select ok(private.inbox_delivery_error((select id from public.messages where guest_reply_to=(select id from public.messages where wa_message_id='concierge-handoff')and direction='out'))like'%opted out%','STOP suppresses all queued service replies');
-- Explicit staff replies remain available during a human conversation, with the same safeguards.
update public.conversations set human_handoff=false,last_inbound_at=now()where id=current_setting('test.guest_conv')::uuid;
insert into public.consent_records(tenant_id,property_id,wa_contact_id,status,source)values('e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','919111111111','opted_in','keyword');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('test.manual_request',extensions.gen_random_uuid()::text,true);
select set_config('test.manual_reply',public.inbox_guest_message(current_setting('test.guest_conv')::uuid,current_setting('test.manual_request')::uuid,'location')::text,true);
select is(public.inbox_guest_message(current_setting('test.guest_conv')::uuid,current_setting('test.manual_request')::uuid,'location'),current_setting('test.manual_reply')::uuid,'staff reply command is idempotent');
select ok(exists(select 1 from jsonb_array_elements(public.inbox_workspace('e3000000-0000-0000-0000-000000000001',jsonb_build_object('c',current_setting('test.guest_conv')))->'messages')m where m->>'id'=current_setting('test.manual_reply')and m->'outbound_payload'is not null),'Inbox exposes the rich payload only through authorized history');
reset role;
update public.conversations set last_inbound_at=now()-interval '25 hours'where id=current_setting('test.guest_conv')::uuid;
select is(private.inbox_delivery_error(current_setting('test.manual_reply')::uuid),'Guest reply window closed.','interactive replies expire with the service window');
set local role authenticated;
select throws_ok(format('select public.inbox_guest_message(%L::uuid,%L::uuid,%L)',current_setting('test.guest_conv'),extensions.gen_random_uuid(),'photos'),'22023',null,'staff cannot bypass reply window');
reset role;
update public.conversations set last_inbound_at=now()where id=current_setting('test.guest_conv')::uuid;
update public.whatsapp_guest_menu set version=version+1 where property_id='e3000000-0000-0000-0000-000000000001';
select is(private.inbox_delivery_error(current_setting('test.manual_reply')::uuid),'Hotel menu or links changed. Send a fresh reply.','editing hotel links invalidates queued snapshots');
update public.whatsapp_guest_authorizations set status='granted',version=version+1 where conversation_id=current_setting('test.guest_conv')::uuid;
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency)values('e5000000-0000-0000-0000-000000000002','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','e4000000-0000-0000-0000-000000000001','confirmed',current_date+7,current_date+9,1000,'INR');
select is(private.whatsapp_verified_menu_stay(current_setting('test.guest_conv')::uuid),null::uuid,'multiple eligible stays require reception instead of guessing');
update public.whatsapp_guest_menu set enabled=false where property_id='e3000000-0000-0000-0000-000000000001';
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','msg:concierge-disabled','919111111111','Asha','concierge-disabled','text','Hello','{}');
reset role;
select is((select count(*)::int from private.whatsapp_guest_inbound_jobs where message_id=(select id from public.messages where wa_message_id='concierge-disabled')),0,'disabled menu does not capture old messages for later replay');
update public.whatsapp_guest_menu set enabled=true where property_id='e3000000-0000-0000-0000-000000000001';
set local role service_role;
select is(public.dispatch_whatsapp_guest_replies(50,'https://guest.test'),0,'enabling menu does not replay past greetings');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok(format('select public.inbox_guest_message(%L::uuid,%L::uuid,%L)',current_setting('test.guest_conv'),extensions.gen_random_uuid(),'location'),'42501',null,'other hotel cannot send a rich reply');
reset role;
select *from finish();rollback;
